import re
from fractions import Fraction

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"(%s)\s*([A-Za-z]+)" % _NUM)
_COMPONENTS_FULL = re.compile(r"\s*%s\s*[A-Za-z]+(?:\s*%s\s*[A-Za-z]+)*\s*" % (_NUM, _NUM))
_ISO = re.compile(
    r"P(?:(%s)W)?(?:(%s)D)?"
    r"(?:T(?:(%s)H)?(?:(%s)M)?(?:(%s)S)?)?" % (_NUM, _NUM, _NUM, _NUM, _NUM),
    re.IGNORECASE,
)
_CLOCK = re.compile(r"\d+(?::\d+){1,2}(?:\.\d*)?|\d+:\d+(?::\d+)?")
_INT = re.compile(r"\d+")


def _round(value):
    # round half up to the nearest whole second
    return int(Fraction(value) + Fraction(1, 2)) if value >= 0 else None


def _finish(total):
    if total < 0:
        raise ValueError("negative duration")
    return int(total + Fraction(1, 2))


def _parse_clock(text):
    parts = text.split(":")
    if len(parts) not in (2, 3):
        raise ValueError("bad clock notation")
    values = []
    for i, p in enumerate(parts):
        if i < len(parts) - 1:
            if not p.isdigit():
                raise ValueError("bad clock notation")
            values.append(Fraction(int(p)))
        else:
            if not re.fullmatch(r"\d+(?:\.\d*)?", p):
                raise ValueError("bad clock notation")
            values.append(Fraction(p))
    # every field after the first must be below 60
    for v in values[1:]:
        if v >= 60:
            raise ValueError("clock field out of range")
    total = Fraction(0)
    for v in values:
        total = total * 60 + v
    return total


def _parse_iso(text):
    m = _ISO.fullmatch(text)
    if not m:
        raise ValueError("bad ISO 8601 duration")
    weeks, days, hours, minutes, seconds = m.groups()
    if all(g is None for g in m.groups()):
        raise ValueError("empty ISO 8601 duration")
    if "T" in text.upper() and text.upper().endswith("T"):
        raise ValueError("dangling T in ISO 8601 duration")
    total = Fraction(0)
    for value, mult in (
        (weeks, 604800), (days, 86400), (hours, 3600), (minutes, 60), (seconds, 1)
    ):
        if value is not None:
            total += Fraction(value) * mult
    return total


def _parse_components(text):
    if not _COMPONENTS_FULL.fullmatch(text):
        raise ValueError("bad duration components")
    total = Fraction(0)
    for num, unit in _COMPONENT.findall(text):
        key = unit.lower()
        if key not in _UNITS:
            raise ValueError("unknown unit: %r" % unit)
        total += Fraction(num) * _UNITS[key]
    return total


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if _INT.fullmatch(s):
        return int(s)
    if s[0] in "Pp":
        return _finish(_parse_iso(s.upper()))
    if ":" in s:
        if not _CLOCK.fullmatch(s):
            raise ValueError("bad clock notation")
        return _finish(_parse_clock(s))
    return _finish(_parse_components(s))

